#pragma once

#include <array>
#include <cstdint>
#include <span>
#include <string_view>

// The em000 family's event codes: what the enemy event handler 0x1401C3130
// spawns for each code 0..0xCE, which (command, frame, code) each CComEm000
// command sends, and each class's command tables. Generated by running the
// handler for every code in an x64 emulator on a fabricated enemy (actor at
// (1, 2, 3), yaw 90 degrees, body joint k at x = 10000 + 1000 k, given
// position (100, 200, 300)). Evidence: docs/research/dmc3-em000-events-2026-10-25.md.
namespace dmc::rengine::profiles::dmc3::em000_events {

inline constexpr std::uint64_t handler_va = 0x1401C3130ULL;
inline constexpr std::uint64_t death_state_va = 0x140095E85ULL;  // sends the death schedule's codes
inline constexpr std::size_t command_table_entries = 128U;

/// Where the handler puts a spawn: on body joint `joint` (mode 0 its world,
/// 1 its position only), at the enemy (and its yaw), or at the event's own
/// position.
enum class Place : std::uint8_t { joint = 0, actor = 1, given = 2 };

struct HandlerSpawn final {
    std::uint8_t code;
    bool type_1a;  ///< enemy type 0x1A takes another path for a few codes
    char kind;
    std::uint16_t id;
    Place place;
    std::uint8_t joint;
    std::uint8_t mode;
    float scale;   ///< uniform scale of the spawn matrix (code 3: 2)
};

struct CommandEvent final {
    std::uint8_t table;  ///< 1: interface slot +0x20 (update), 2: +0x28 (start)
    std::uint8_t command;
    float frame;         ///< the motion frame the command waits for
    std::uint8_t code;   ///< the event code it sends
};

struct ClassTables final {
    std::string_view name;
    /// (bank, action) for table 1's 128 commands, then table 2's.
    std::array<std::array<std::uint8_t, 2>, 2U * command_table_entries> pairs;
};

[[nodiscard]] std::span<const HandlerSpawn> handler_spawns() noexcept;
[[nodiscard]] std::span<const CommandEvent> command_events() noexcept;
[[nodiscard]] std::span<const ClassTables> class_tables() noexcept;

} // namespace dmc::rengine::profiles::dmc3::em000_events
